                    @foreach (var category in _categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="cat-@category"
                                   checked="@_selectedCategories.Contains(category)"
                                   @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                            <label class="form-check-label" for="cat-@category">@category</label>
                        </div>
                    }
                </div>
            }

            <div class="mb-3">
                <label class="form-label fw-semibold">Price Range</label>
                <div class="d-flex gap-2">
                    <input type="number" class="form-control" placeholder="Min" min="0"
                           @bind="_minPrice" @bind:event="oninput" />
                    <input type="number" class="form-control" placeholder="Max" min="0"
                           @bind="_maxPrice" @bind:event="oninput" />
                </div>
            </div>

            <div class="form-check mb-3">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="_inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>

            <div class="d-grid gap-2">
                <button class="btn btn-primary" @onclick="ApplyFiltersAsync">Apply Filters</button>
                <button class="btn btn-outline-secondary" @onclick="ClearFiltersAsync">Clear Filters</button>
            </div>
        </aside>

        <!-- Main content -->
        <div class="catalog-main flex-grow-1">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label me-2 mb-0">Sort by:</label>
                    <select class="form-select d-inline-block w-auto" @onchange="OnSortChangedAsync">
                        @foreach (var option in _sortOptions)
                        {
                            <option value="@option.Value" selected="@(option.Value == _sortBy)">@option.Label</option>
                        }
                    </select>
                </div>

                @if (_result is not null && _result.TotalCount > 0)
                {
                    var first = (_result.Page - 1) * _result.PageSize + 1;
                    var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                    <span class="text-muted">Showing @first–@last of @_result.TotalCount products</span>
                }
            </div>

